CREATE TYPE "CashTransactionType" AS ENUM ('INFLOW','OUTFLOW');
CREATE TYPE "OperationalExpenseCategory" AS ENUM ('KESEJAHTERAAN_MANAJER','KESEJAHTERAAN_PEGAWAI','MAKAN_MINUM','BANTUAN_TRANSPORTASI','HONORARIUM_NARASUMBER','HONORARIUM_SIDANG');
CREATE TABLE "cash_accounts" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"balance" DECIMAL(18,2) NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "cash_accounts_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "cash_accounts_code_key" ON "cash_accounts"("code");
CREATE TABLE "cash_transactions" ("id" TEXT NOT NULL,"reference" TEXT NOT NULL,"accountId" TEXT NOT NULL,"type" "CashTransactionType" NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"transactionDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"description" TEXT NOT NULL,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "cash_transactions_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "cash_transactions_reference_key" ON "cash_transactions"("reference"); CREATE INDEX "cash_transactions_accountId_transactionDate_idx" ON "cash_transactions"("accountId","transactionDate"); ALTER TABLE "cash_transactions" ADD CONSTRAINT "cash_transactions_accountId_fkey" FOREIGN KEY("accountId") REFERENCES "cash_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "operational_expenses" ("id" TEXT NOT NULL,"expenseNumber" TEXT NOT NULL,"category" "OperationalExpenseCategory" NOT NULL,"accountId" TEXT NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"transactionDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"recipient" TEXT,"description" TEXT NOT NULL,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "operational_expenses_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "operational_expenses_expenseNumber_key" ON "operational_expenses"("expenseNumber"); CREATE INDEX "operational_expenses_transactionDate_category_idx" ON "operational_expenses"("transactionDate","category"); ALTER TABLE "operational_expenses" ADD CONSTRAINT "operational_expenses_accountId_fkey" FOREIGN KEY("accountId") REFERENCES "cash_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
